import {clockCases,clockPages} from './preparation-clock-content.mjs';
import {clockView,startClock,resumeClock,setClockPage,chooseClockReading,chooseClockSetting,stepClock,addClockSupport,checkClock,clockCheckMatches,clockLabel,clockPictureText,readingLabel} from './preparation-clock-core.mjs';
import {preparationClockDiagram} from './preparation-clock-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const readingChoice=(source,value)=>value===null?'No reading chosen':value==='unsure'?'Not sure yet':readingLabel(source,value);
const settingChoice=value=>value==='clock'?'Use this model clock':value==='unsure'?'Not sure yet':'No setting response yet';
const result=value=>value===null?'unobserved':value?'fits':'does not fit';
const recordHeading=(r,c,i)=>i<r.checks.length-1?'Earlier recorded check':clockCheckMatches(r,c)?'Latest check of these choices':'Latest check · choices or support changed since';
function figure(source,slot,model=false){const description=model?clockPictureText(slot):source.pictureText;return `<figure class="clock-figure"><figcaption>${model?'Our model · proposed departure':'Fixed preparation clock'}</figcaption>${source.drawingVersion===1?preparationClockDiagram(slot,{pictureText:description,label:model?'Our model clock':'Fixed preparation clock'}):`<div class="clock-picture-fallback"><p>This saved picture version is unavailable.</p><p>${esc(description)}</p>${model?`<p>Supplied model-position label: <strong>${esc(clockLabel(slot))}</strong>.</p>`:''}</div>`}<p class="clock-hand-legend"><span><i class="clock-hour-key" aria-hidden="true"></i> Short hand: hour</span><span><i class="clock-minute-key" aria-hidden="true"></i> Long hand: minute</span></p><details class="clock-picture-description"><summary>Clock picture description</summary><p>${esc(description)}</p></details></figure>`;}
function readPage(r){return `<h2 id="clock-prompt" tabindex="-1">${esc(r.source.readingPrompt)}</h2><p class="clock-story">${esc(r.source.story)}</p><div class="clock-turn"><div>${figure(r.source,r.source.preparationSlot)}</div><section class="clock-answer"><div class="clock-reading-options" role="group" aria-label="Choose the digital preparation time">${r.source.readingOptions.map(o=>button(`data-clock-reading="${o.slot}" aria-pressed="${r.reading===o.slot}"`,o.label+(r.reading===o.slot?' · selected':''),r.reading===o.slot)).join('')}${button(`data-clock-reading="unsure" aria-pressed="${r.reading==='unsure'}"`,'Not sure yet',r.reading==='unsure')}</div>${button('data-clock-reading="blank"','Leave reading blank')}${hearButton(r.source.readingPrompt+' '+r.source.pictureText,'Hear the question and picture description')}${button('data-clock-page="set"','Next: set the departure',true)}</section></div>`;}
function setPage(r){return `<h2 id="clock-prompt" tabindex="-1">${esc(r.source.settingPrompt)}</h2><p class="clock-goal">Requested departure: <strong>${esc(r.source.departureLabel)}</strong></p><div class="clock-turn"><div>${figure(r.source,r.position,true)}</div><section class="clock-answer"><div class="clock-step-controls" role="group" aria-label="Move both model clock hands together">${[[-1,'Back 30 minutes'],[1,'Forward 30 minutes'],[-2,'Back 1 hour'],[2,'Forward 1 hour']].map(([delta,label])=>button(`data-clock-step="${delta}"`,label)).join('')}</div><p class="clock-proposal-status">${r.settingChoice==='clock'?'This model is our proposed departure.':r.settingChoice==='unsure'?'Not sure is selected. The model position is retained; it is not an active departure response.':'No setting response yet. Move the model or explicitly use this clock.'}</p><div class="clock-setting-options" role="group" aria-label="Choose a departure response">${button(`data-clock-setting="clock" aria-pressed="${r.settingChoice==='clock'}"`,'Use this clock as our departure',r.settingChoice==='clock')}${button(`data-clock-setting="unsure" aria-pressed="${r.settingChoice==='unsure'}"`,'Not sure yet',r.settingChoice==='unsure')}</div>${button('data-clock-check','Check / keep this trail',true)}<p class="tiny">Latest 8 checks stay here; a ninth removes the oldest. Checking is open with blank choices.</p></section></div><p class="tiny">Earlier reading choice: ${esc(readingChoice(r.source,r.reading))}. The fixed preparation picture stays on Read.</p>${button('data-clock-page="read"','Read the preparation clock')}<details id="clock-digital" data-round="${r.id}"><summary>Show our model’s current digital label</summary><p>Supplied model-position label: <strong>${esc(clockLabel(r.position))}</strong>.</p><p>These steps coordinate both hands. A face position alone does not tell us which day or clock cycle it is.</p></details>`;}
function frozenSource(source){return `<details><summary>Original preparation card and fixed-picture description</summary><h4>${esc(source.title)}</h4><p>${esc(source.story)}</p><p>${esc(source.readingPrompt)}</p><p>Fixed preparation picture: ${esc(source.pictureText)}</p><p>Supplied reading options: ${source.readingOptions.map(o=>esc(o.label)).join(' / ')}.</p><p>${esc(source.settingPrompt)} Requested departure: ${esc(source.departureLabel)}.</p><p>${esc(source.help)}</p></details>`;}
function checkRecord(r,c,i){return `<section class="clock-record" tabindex="-1"><h3>${recordHeading(r,c,i)}</h3><p class="clock-feedback">${esc(c.feedback)}</p><p><strong>Recorded reading:</strong> ${esc(c.readingLabel===null?'No definite digital label recorded':c.readingLabel)} · ${result(c.readingMatch)}.<br><strong>Recorded departure response:</strong> ${esc(settingChoice(c.input.settingChoice))} · ${result(c.settingMatch)}.<br><strong>Recorded both responses fit:</strong> ${c.fulfilled?'yes':'no'}.</p><details><summary>Choices and picture descriptions kept with this check</summary><p>Reading input: ${esc(c.input.reading===null?'blank':c.input.reading==='unsure'?'not sure':`slot ${c.input.reading}`)}. Model input: slot ${c.input.position}. Setting response: ${esc(settingChoice(c.input.settingChoice))}.</p><p>Recorded model label: ${esc(c.modelLabel)}.</p><p>Recorded preparation-picture description: ${esc(c.readingPictureText)}</p><p>Recorded model-picture description: ${esc(c.modelPictureText)}</p><p>Support requested by this check: ${esc(c.input.support.join(', ')||'none recorded')}.</p><p class="tiny">These labels, descriptions and outcomes are recorded snapshots.</p></details>${frozenSource(c.source)}</section>`;}
function keptPage(r){return `<h2 id="clock-prompt" tabindex="-1">Our kept clock trail</h2>${r.checks.length?checkRecord(r,r.checks.at(-1),r.checks.length-1):'<p>No check kept yet. Both responses are still open.</p>'}${button('data-clock-page="set"','Revise our departure',true)} ${button('data-clock-page="read"','Read the fixed preparation clock')}${r.checks.length>1?`<details><summary>Earlier checks (${r.checks.length-1})</summary>${r.checks.slice(0,-1).map((c,i)=>checkRecord(r,c,i)).join('')}</details>`:''}`;}
function catalog(v){const n=Math.max(0,v.rounds.length-11);return `<section class="clock-catalog"><h2>Choose a preparation card</h2><p>Four fictional market jobs, all open. Starting a card creates a separate visit.</p><p class="tiny">Up to 12 readable visits stay here.${n?` Starting now removes the oldest ${n} readable ${n===1?'visit':'visits'}.`:' Earlier visits remain within that limit.'}</p><form id="clock-start-form"><label for="clock-case">Preparation card</label><select id="clock-case" name="case">${clockCases.map(c=>`<option value="${esc(c.id)}"${v.current?.source.id===c.id?' selected':''}>${esc(c.title)}</option>`).join('')}</select><button type="submit" class="secondary">Start this card</button></form></section>`;}
function history(v){return `${v.rounds.length?`<details><summary>Our clock visits (${v.rounds.length})</summary>${[...v.rounds].reverse().map(r=>`<p>${button(`data-clock-resume="${r.id}"`,`Visit ${r.id}: ${r.source.title}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable clock work (${v.earlier.length})</summary><p>The original work remains unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function preparationClockPage(state){const v=clockView(state),r=v.current,header=`<header class="page-heading"><a class="back" href="#workshop"><span aria-hidden="true">←</span> Workshop</a> <a class="back" href="#post">Post Office</a><h1>Preparation Clock</h1><p>Read the preparation clock, then set a model for a market departure.</p></header>`;if(v.status==='unavailable')return `<div class="clock-page">${header}<section class="clock-sheet"><h2>Earlier clock work is safe</h2><p>This saved format cannot be continued here. Other Workshop tools remain open.</p><details><summary>Saved clock work</summary><pre>${esc(JSON.stringify(state.preparationClock,null,2))}</pre></details></section></div>`;return `<div class="clock-page">${header}<section class="clock-sheet">${r?`<nav class="clock-tabs" aria-label="Preparation Clock pages">${clockPages.map(p=>button(`data-clock-page="${p}" aria-current="${v.page===p?'page':'false'}"`,({read:'Read',set:'Set',kept:'Kept trail'})[p],v.page===p)).join('')}</nav><p class="clock-case-title"><strong>${esc(r.source.title)}</strong>${r.familiar?' · Case visited before':''}</p>`:''}<p id="clock-status" role="status" tabindex="-1"></p>${r?v.page==='set'?setPage(r):v.page==='kept'?keptPage(r):readPage(r):`<h2 id="clock-prompt" tabindex="-1">A clock for our pretend preparation table</h2><p>Read one fixed clock and set another. These are model faces, not real appointments or timers.</p>${catalog(v)}`}${r?`<details id="clock-help" data-round="${r.id}"><summary>Help us read and set the clock</summary><p>${esc(r.source.help)}</p>${hearButton(r.source.help,'Hear the clock explanation')}${button('data-clock-together',r.support.includes('together')?'Thinking together recorded':'We thought together')}</details><details><summary>Choose another preparation card</summary>${catalog(v)}</details>`:''}</section>${history(v)}</div>`;}
export function preparationClockNotes(state){const v=clockView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Preparation Clock · earlier format</summary><pre>${esc(JSON.stringify(state.preparationClock,null,2))}</pre></details>`;return `<details class="panel clock-page"><summary>Preparation Clock (${v.rounds.length} visits)</summary><p>Guided analogue/digital hour-and-half-hour practice with coupled model hands. Fitting choices do not establish independent clock reading, drawing, hand placement, elapsed-duration calculation or physical time measurement. Support is a per-visit record; different cases may share the same preparation picture.</p>${v.rounds.map(r=>`<section><h3>Visit ${r.id}: ${esc(r.source.title)}</h3><p>Case visited before: ${r.familiar?'yes':'no'}. Current reading: ${esc(readingChoice(r.source,r.reading))}. Current model position: ${esc(clockLabel(r.position))}. Current setting response: ${esc(settingChoice(r.settingChoice))}. Support: ${esc(r.support.join(', ')||'none recorded')}.</p>${frozenSource(r.source)}${r.checks.map((c,i)=>checkRecord(r,c,i)).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindPreparationClock(state,{save,render,focus}){
 const boundId=clockView(state).current?.id,sameVisit=el=>el.isConnected&&boundId!==undefined&&clockView(state).current?.id===boundId;
 const show=(message='',target='#clock-prompt')=>{const id=clockView(state).current?.id,open=[...document.querySelectorAll('.clock-sheet details[id][data-round][open]')].filter(d=>Number(d.dataset.round)===id).map(d=>d.id);save();render();if(clockView(state).current?.id===id)for(const key of open){const d=document.getElementById(key);if(d)d.open=true;}const status=document.querySelector('#clock-status');if(status)status.textContent=message;focus?.(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b))fn(b);}));
 const saveSupport=code=>{addClockSupport(state,code);save();const r=clockView(state).current,h=document.querySelector('.clock-sheet .clock-record h3');if(h&&r?.checks.length){h.textContent=recordHeading(r,r.checks.at(-1),r.checks.length-1);const status=document.querySelector('#clock-status');if(status)status.textContent='Support request recorded. '+h.textContent+'.';}};
 document.querySelector('#clock-start-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.isConnected||clockView(state).current?.id!==boundId)return;const r=startClock(state,new FormData(form).get('case'));show(r?'A preparation card is ready.':'A new visit cannot be created because its saved visit numbers have reached the supported limit.',r?'#clock-prompt':'#clock-status');});
 document.querySelectorAll('[data-clock-resume]').forEach(b=>b.addEventListener('click',()=>{if(!b.isConnected||clockView(state).current?.id!==boundId)return;show(resumeClock(state,Number(b.dataset.clockResume))?'Earlier clock visit opened with its own card.':'That visit could not be opened.');}));
 bind('[data-clock-page]',b=>{setClockPage(state,b.dataset.clockPage);show();});
 bind('[data-clock-reading]',b=>{chooseClockReading(state,b.dataset.clockReading==='blank'?null:b.dataset.clockReading==='unsure'?'unsure':Number(b.dataset.clockReading));show('Reading choice changed. The departure model is unchanged.',`[data-clock-reading="${b.dataset.clockReading}"]`);});
 bind('[data-clock-step]',b=>{stepClock(state,Number(b.dataset.clockStep));show('Both hands moved together. This model is now our proposed departure.',`[data-clock-step="${b.dataset.clockStep}"]`);});
 bind('[data-clock-setting]',b=>{chooseClockSetting(state,b.dataset.clockSetting);show(b.dataset.clockSetting==='clock'?'This model is now our proposed departure.':'Not sure selected; the model is retained for revision.',`[data-clock-setting="${b.dataset.clockSetting}"]`);});
 bind('[data-clock-check]',()=>{const c=checkClock(state);if(c)setClockPage(state,'kept');show(c?'The reading and setting responses are kept separately.':'This check could not be kept.',c?'.clock-record':'#clock-status');});
 bind('[data-clock-together]',()=>{addClockSupport(state,'together');show('Thinking together recorded as support.','[data-clock-together]');});
 for(const [id,code]of [['clock-help','help'],['clock-digital','digital']]){const fold=document.getElementById(id);fold?.addEventListener('toggle',()=>{if(fold.open&&sameVisit(fold)&&Number(fold.dataset.round)===boundId){saveSupport(code);}});}
 document.querySelectorAll('.clock-sheet [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b)){saveSupport('audio');}}));
}
